Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site/docs', 'closed/docs', 'small/docs' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/docs/readme.txt'), "read me first`n")
[IO.File]::WriteAllText((Join-Path $PWD 'closed/docs/readme.txt'), "read me first`n")
[IO.File]::WriteAllText((Join-Path $PWD 'small/docs/readme.txt'), "read me first`n")
[IO.File]::WriteAllText((Join-Path $PWD 'report.txt'), "quarterly numbers`n")
[IO.File]::WriteAllText((Join-Path $PWD 'report2.txt'), "revised numbers`n")
$server0 = Start-Process surl -ArgumentList '--directory', 'site', '--allow-uploads', '--auth', 'ntlmv1,digest', '-u', 'alice:s3cret', 'smb://127.0.0.1:8080/', 'http://127.0.0.1:8081/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -u alice:s3cret -T report.txt smb://127.0.0.1:8080/docs/report.txt } finally { Stop-Process $server0 }
